<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set up MFA - <?php echo htmlspecialchars(SITENAME); ?></title><style>body{font-family:Arial,sans-serif;background:#f1f5f9;display:grid;place-items:center;min-height:100vh;margin:0}.card{background:#fff;padding:32px;border-radius:16px;max-width:560px;width:calc(100% - 48px);box-shadow:0 16px 40px #0f172a18}code{display:block;padding:12px;background:#f8fafc;overflow-wrap:anywhere}input,button{box-sizing:border-box;width:100%;padding:12px;margin-top:10px;border-radius:8px}input{border:1px solid #cbd5e1}button{border:0;background:#0f766e;color:#fff;font-weight:700}.error{color:#b91c1c}</style></head><body><main class="card"><h1>Secure your administrator account</h1><p>Add this account to a TOTP-compatible authenticator using the secret or provisioning URI below.</p><strong>Secret</strong><code><?php echo htmlspecialchars($secret); ?></code><details><summary>Show provisioning URI</summary><code><?php echo htmlspecialchars($provisioningUri); ?></code></details><?php if ($error): ?><p class="error"><?php echo htmlspecialchars($error); ?></p><?php endif; ?><form method="post"><?php echo csrfInput(); ?><label for="code">Enter the generated six-digit code</label><input id="code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required><button type="submit">Enable MFA</button></form></main></body></html>
